import React from 'react';
import classnames from 'clsx';
import {
  BorderColor,
  Display,
  AlignItems,
  JustifyContent,
  BackgroundColor,
  IconColor,
  TextColor,
} from '../../../helpers/constants/design-system';

import { Icon } from '../icon';
import type { PolymorphicRef } from '../box';
import { AvatarBase, AvatarBaseProps } from '../avatar-base';
import type { AvatarIconComponent } from './avatar-icon.types';
import {
  AvatarIconProps,
  AvatarIconSize,
  avatarIconSizeToIconSize,
} from './avatar-icon.types';

/**
 * @deprecated Please update your code to use `AvatarIcon` from `@metamask/design-system-react`.
 * @see {@link https://github.com/MetaMask/metamask-design-system/blob/main/packages/design-system-react/MIGRATION.md#from-extension-component-library | Migration Guide}
 * @see {@link https://metamask.github.io/metamask-design-system/?path=/docs/react-components-avataricon--docs | Storybook Documentation}
 */
export const AvatarIcon: AvatarIconComponent = React.forwardRef(
  // TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
  // eslint-disable-next-line @typescript-eslint/naming-convention
  <C extends React.ElementType = 'div'>(
    {
      size = AvatarIconSize.Md,
      color = TextColor.primaryDefault,
      backgroundColor = BackgroundColor.primaryMuted,
      className = '',
      iconProps,
      iconName,
      ...props
    }: AvatarIconProps<C>,
    ref?: PolymorphicRef<C>,
  ) => {
    const iconSize = avatarIconSizeToIconSize[size];
    return (
      <AvatarBase
        ref={ref}
        size={size}
        display={Display.Flex}
        alignItems={AlignItems.center}
        justifyContent={JustifyContent.center}
        color={color as TextColor}
        backgroundColor={backgroundColor}
        borderColor={BorderColor.transparent}
        className={classnames('mm-avatar-icon', className)}
        {...(props as AvatarBaseProps<C>)}
      >
        <Icon
          color={IconColor.inherit}
          name={iconName}
          size={iconSize}
          {...iconProps}
        />
      </AvatarBase>
    );
  },
);
